    "about_topic": true,
    "says": "rule: wait for a smaller vehicle to move right before passing it when making a left turn"
   },
   {
    "id": "c6",
    "about_topic": true,
    "says": "rule: do not pull up beside a larger vehicle to make a left turn at the same time"
   },
   {
    "id": "c7",
    "about_topic": true,
    "says": "rule: stay behind the vehicle and turn when the way is clear"
   },
   {
    "id": "m19",
    "about_topic": true,
    "says": "rule: left-turn lanes are not to be used for passing"
   }
  ],
  "statements": [
   {
    "id": "s1",
    "type": "RULE",
    "force": "ADVISORY",
    "force_from": "imperative (\"Wait\")",
    "text": "a driver SHOULD wait for the smaller vehicle to move right WHEN the driver is making a left turn AND the driver is behind a smaller vehicle UNTIL the smaller vehicle moves right",
    "sources": [
     {
      "id": "m53",
      "quote": "Wait for the smaller vehicle to move right before you pass."
     }
    ],
    "flags": [],
    "links": [],
    "note": "The context of 'making a left turn' is inferred from the heading 'Left turns' and the surrounding context of c6/c7 which discuss turning behind vehicles."
   },
   {
    "id": "s2",
    "type": "RULE",
    "force": "ADVISORY",
    "force_from": "imperative (\"do not pull up\")",
    "text": "a driver SHOULD NOT pull up beside a vehicle to make a left turn at the same time WHEN the driver is making a left turn behind the vehicle",
    "sources": [
     {
      "id": "c6",
      "quote": "If you are making a left turn behind one of these vehicles, do not pull up beside it to make your turn at the same time."
     }
    ],
    "flags": [],
    "links": [],
    "note": "The phrase 'one of these vehicles' refers to vehicles discussed in the preceding context (likely larger or slower vehicles), but the rule applies to any vehicle ahead in the lane when turning left."
   },
   {
    "id": "s3",
    "type": "RULE",
    "force": "ADVISORY",
    "force_from": "imperative (\"Stay\", \"turn\")",
    "text": "a driver SHOULD stay behind the vehicle AND turn WHEN the driver is making a left turn behind the vehicle UNTIL the way is clear",
    "sources": [
     {
      "id": "c7",
      "quote": "Stay behind and turn when the way is clear."
     }
    ],
    "flags": [
