   },
   {
    "id": "s4",
    "type": "RULE",
    "force": "LEGAL",
    "force_from": "text (\"not to be used\")",
    "text": "a driver MUST NOT use a left-turn lane for passing",
    "sources": [
     {
      "id": "m19",
      "quote": "These left-turn lanes are not to be used for passing."
     }
